async function prepararNteCadastro(f,ntePreferido=null){const sel=$('#leg-nte-select'),svc=window.SIGEE_LEGALIZACAO_SERVICE;if(!sel)return;sel.innerHTML='<option value="">Carregando NTE…</option>';try{const ntes=await svc.listarNtes(),atual=svc.nteId?.(),fixar=atual!=null&&atual!=='';sel.innerHTML='<option value="">Selecione</option>'+ntes.map(n=>`<option value="${esc(n.id)}" ${String(n.id)===String(ntePreferido??atual)?'selected':''}>NTE ${esc(n.numero||n.id)}${n.nome?' · '+esc(n.nome):''}</option>`).join('');sel.disabled=fixar;if(fixar){let hidden=f.querySelector('input[name="nte_id_fixo"]');if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.name='nte_id_fixo';f.appendChild(hidden);}hidden.value=atual;$('#leg-nte-ajuda').textContent='NTE fixado pelo cadastro do usuário.';}else{$('#leg-nte-ajuda').textContent='Selecione o NTE para usuário com abrangência global.';}preencherMunicipiosCadastro(f,ntePreferido??atual);}catch(_){sel.innerHTML='<option value="">NTE indisponível</option>';}if(!sel.dataset.municipiosBound){sel.dataset.municipiosBound='1';sel.addEventListener('change',()=>preencherMunicipiosCadastro(f,sel.value));}}
