function preencherCampo(form,nome,valor){const el=form.elements?.[nome];if(!el)return;el.value=valor??'';if(['cep'].includes(nome))el.value=formatarCep(valor||'');if(nome.includes('cpf'))el.value=formatarCpf(valor||'');if(nome.includes('cnpj'))el.value=formatarCnpj(valor||'');if(nome.includes('telefone')||nome.includes('whatsapp'))el.value=formatarTelefone(valor||'');}
