function statusChecklistLabel(v){return ({NAO_APRESENTADO:'Não apresentado',APRESENTADO:'Apresentado',EM_ANALISE:'Em análise',CONFORME:'Conforme',NAO_CONFORME:'Não conforme',NAO_SE_APLICA:'Não se aplica'})[upper(v)]||v;}
function resumoChecklist(items){const total=items.length,ok=items.filter(i=>['APRESENTADO','CONFORME','NAO_SE_APLICA'].includes(upper(i.status))).length,pend=items.filter(i=>!['APRESENTADO','CONFORME','NAO_SE_APLICA'].includes(upper(i.status))).length;return{total,ok,pend,pct:total?Math.round(ok*100/total):0};}
