async function abrirProntuario(id,porEscola=false,abaInicial='cadastro'){if(!allowed())return;const m=ensureProntuario(),h=$('#leg-prontuario-host');m.classList.remove('hidden');h.innerHTML='<div class="leg-loading">Consolidando prontuário institucional…</div>';try{prontuarioAtual=porEscola?await window.SIGEE_LEGALIZACAO_SERVICE.obterProntuarioPorEscola(id):await window.SIGEE_LEGALIZACAO_SERVICE.obterProntuario(id);renderProntuario(abaInicial||'cadastro');}catch(err){h.innerHTML=`<div class="leg-empty danger"><strong>Falha ao carregar prontuário.</strong><span>${esc(err.message||err)}</span></div>`;}}
